import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, Validators, FormArray } from '@angular/forms';
import { HouseService } from '../../../house/services/house.service';
import { OwnerService } from '../../../owner/services/owner.service';
import { Owner } from '../../../owner/models/owner.model';
import { Observable } from 'rxjs';
import { House } from '../../../house/models/house.model';

@Component({
  selector: 'app-create-house',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: 'add-house.component.html',
  styleUrls: ['add-house.component.scss']
})
export class AddHouseComponent implements OnInit {

  houseId?: string;
  $house!: Observable<House>;
  $owners!: Observable<Owner>;

  form: any;
  imagePreviews: string[] = [];
  selectedFiles: File[] = [];
  isLoading = false;

  constructor(
    private fb: FormBuilder,
    private houseService: HouseService,
    private ownerService: OwnerService,
    private router: Router,
    private route: ActivatedRoute
  ) {

    this.form = this.fb.group({
      title: ['', Validators.required],
      price: ['', Validators.required],
      description: ['', Validators.required],
      type: ['', Validators.required],
      rooms: ['', Validators.required],
      neighboorhood: ['', Validators.required],
      city: ['', Validators.required],
      idOwner: ['', Validators.required],
      rating: [''],
      availability: [true],
      equipments: this.fb.array([])
    });

    this.$owners = this.ownerService.getOwnerByToken();
    this.$owners.subscribe(owner => {
      this.form.get('idOwner')?.setValue(owner._id);
    });
  }

  ngOnInit(): void {
    this.houseId = this.route.snapshot.params['id'];
    if (this.houseId) {
      this.getHouseById(this.houseId);
    }
  }

  /* ===================== IMAGES ===================== */

  onFilesSelected(event: any) {
    const files: FileList = event.target.files;

    this.imagePreviews = [];
    this.selectedFiles = [];

    Array.from(files).forEach(file => {
      this.selectedFiles.push(file);
      const reader = new FileReader();
      reader.onload = (e: any) => this.imagePreviews.push(e.target.result);
      reader.readAsDataURL(file);
    });
  }

  removeImage(index: number) {
    this.imagePreviews.splice(index, 1);
    this.selectedFiles.splice(index, 1);
  }

  selectType(type: string) {
    this.form.patchValue({ type });
  }

  /* ===================== EQUIPMENTS ===================== */

  get equipments(): FormArray {
    return this.form.get('equipments') as FormArray;
  }

  addEquipment(value: string = '') {
    this.equipments.push(this.fb.control(value));
  }

  removeEquipment(i: number) {
    this.equipments.removeAt(i);
  }

  /* ===================== LOAD HOUSE ===================== */

  getHouseById(id: string) {
    this.houseService.getHouseById(id).subscribe({
      next: (house) => {
        this.form.patchValue(house);

        this.equipments.clear();
        if (house.equipments?.length) {
          house.equipments.forEach((eq: string) => {
            this.equipments.push(this.fb.control(eq));
          });
        }

        if (house.imageUrl?.length) {
          this.imagePreviews = [...house.imageUrl];
        }
      },
      error: err => console.error(err)
    });
  }

  /* ===================== SUBMIT ===================== */

  isSuccess = false;

  submit() {
    if (this.form.invalid) return;

    const formData = new FormData();

    // ✅ Envoi uniquement des champs valides (SAFE UPDATE)
    Object.entries(this.form.value).forEach(([key, value]) => {
      if (
        key !== 'equipments' &&
        value !== null &&
        value !== undefined &&
        value !== ''
      ) {
        formData.append(key, String(value));
      }
    });

    // ✅ Equipments
    this.equipments.value.forEach((eq: string) => {
      formData.append('equipments[]', eq);
    });

    // ✅ Images (New files)
    this.selectedFiles.forEach(file => {
      formData.append('images', file);
    });

    // ✅ Existing Images (URLs)
    this.imagePreviews.forEach(preview => {
      if (typeof preview === 'string' && preview.startsWith('http')) {
        formData.append('existingImages', preview);
      }
    });

    this.isLoading = true;

    const request$ = this.houseId
      ? this.houseService.updateHouse(this.houseId, formData)
      : this.houseService.addHouse(formData);

    request$.subscribe({
      next: () => {
        this.isLoading = false;
        this.isSuccess = true;
        this.houseService.clearCache(); // Invalider le cache page 1
        setTimeout(() => {
          this.router.navigate(this.houseId ? ['/admin/allOwnerHouses'] : ['/']);
        }, 2000);
      },
      error: err => {
        console.error(err);
        this.isLoading = false;
        // Optional: Add isError state handling here if requested later
        alert("Une erreur est survenue lors de l'opération.");
      }
    });
  }
}
