import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

import { AdminServiceService } from '../../services/admin-service.service';
import { HouseService } from '../../../house/services/house.service';
import { CommonModule } from '@angular/common';
@Component({
  selector: 'app-all-owner-houses',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './all-owner-houses.component.html',
  styleUrl: './all-owner-houses.component.scss'
})
export class AllOwnerHousesComponent implements OnInit {
  houses: any[] = [];
  isLoading = false;
  errorMessage: string = '';

  constructor(
    private adminService: AdminServiceService,
    private houseService: HouseService,
    private router: Router
  ) { }

  ngOnInit(): void {
    this.fetchHouses();
  }

  fetchHouses() {
    this.isLoading = true;
    this.adminService.getOwnerHouses().subscribe({
      next: (res: any) => {
        this.houses = res;
        this.isLoading = false;
      },
      error: (err) => {
        console.error("Error fetching houses", err);
        this.errorMessage = "Impossible de récupérer vos propriétés.";
        this.isLoading = false;
      }
    });
  }

  onEditHouse(house: any) {
    this.router.navigate(['/admin/addHouse', { id: house._id }]);
  }


  /* ===================== MODAL LOGIC ===================== */
  verificationModal = {
    show: false,
    house: null as any,
    message: ''
  };

  onToggleStatus(house: any) {
    const action = house.isActive ? 'désactiver' : 'activer';
    this.verificationModal = {
      show: true,
      house: house,
      message: `Voulez-vous vraiment ${action} cette annonce ?`
    };
  }

  confirmToggle() {
    if (!this.verificationModal.house) return;

    const house = this.verificationModal.house;
    this.isLoading = true; // Optional: show loading in modal or global
    this.closeModal(); // Close immediately or wait? Better close and show global loader if needed, or keeping loading state. 
    // Let's keep global loader logic from before but updated.

    this.houseService.toggleStatus(house._id).subscribe({
      next: (updatedHouse: any) => {
        const index = this.houses.findIndex(h => h._id === house._id);
        if (index !== -1) {
          this.houses[index] = updatedHouse.house;
        }
        this.isLoading = false;
      },
      error: (err) => {
        console.error("Error toggling status", err);
        // Optionally show error in a toast or modal
        this.isLoading = false;
      }
    });
  }

  closeModal() {
    this.verificationModal = { show: false, house: null, message: '' };
  }
}
