import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
// import { DashboardComponent } from './components/dashboard/dashboard.component';
import { AppAdminComponent } from './components/app-admin/app-admin.component';
import { DashboardComponent } from './components/dashboard/dashboard.component';
import { AddHouseComponent } from './components/add-house/add-house.component';
import { AllOwnerHousesComponent } from './components/all-owner-houses/all-owner-houses.component';

const routes: Routes = [
  {
    path: '',
    component: AppAdminComponent,   // Layout admin (sidebar + router-outlet)
    children: [
      { path: '', component: DashboardComponent },
      { path: 'addHouse', component: AddHouseComponent },
      { path: 'allOwnerHouses', component: AllOwnerHousesComponent },
      { path: 'houses/:id', component: AddHouseComponent },


    ]
  }
];
@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class AdminRoutingModule {

}
